package com.yeyamo_mobile.api.notification_service.application;
import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.yeyamo_mobile.api.notification_service.application.port.*;import com.yeyamo_mobile.api.notification_service.domain.*;
@Service public class NotificationApplicationService{private final NotificationRepositoryPort notifications;private final PreferenceRepositoryPort preferences;private final TemplatePort templates;private final DeliveryRepositoryPort deliveries;private final DevicePushTokenRepositoryPort devices;public NotificationApplicationService(NotificationRepositoryPort n,PreferenceRepositoryPort p,TemplatePort t,DeliveryRepositoryPort d,DevicePushTokenRepositoryPort devices){notifications=n;preferences=p;templates=t;deliveries=d;this.devices=devices;}@Transactional public Optional<Notification>create(NotificationIntent intent){if(notifications.exists(intent.sourceEventId(),intent.recipientId()))return Optional.empty();NotificationPreference pref=preferences.find(intent.recipientId()).orElseGet(()->preferences.save(NotificationPreference.defaults(intent.recipientId(),intent.email())));Map<String,String>vars=new LinkedHashMap<>(intent.variables()==null?Map.of():intent.variables());RenderedTemplate inApp=templates.render(intent.eventType(),NotificationChannel.IN_APP,pref.locale(),vars);vars.putIfAbsent("message",inApp.body());Notification n=notifications.save(new Notification(UUID.randomUUID(),intent.sourceEventId(),intent.eventType(),intent.recipientId(),inApp.subject(),inApp.body(),intent.dataJson()==null?"{}":intent.dataJson(),Instant.now(),null));for(NotificationChannel channel:NotificationChannel.values()){if(!pref.enabled(channel))continue;RenderedTemplate rendered=channel==NotificationChannel.IN_APP?inApp:templates.render(intent.eventType(),channel,pref.locale(),vars);if(channel==NotificationChannel.PUSH){for(DevicePushToken device:devices.findEnabledByUserId(intent.recipientId()))createDelivery(n,channel,device.token(),rendered);continue;}createDelivery(n,channel,pref.destination(channel),rendered);}return Optional.of(n);}private void createDelivery(Notification n,NotificationChannel channel,String destination,RenderedTemplate rendered){DeliveryStatus status=channel==NotificationChannel.IN_APP?DeliveryStatus.SENT:DeliveryStatus.PENDING;Instant delivered=channel==NotificationChannel.IN_APP?Instant.now():null;deliveries.save(new Delivery(UUID.randomUUID(),n.id(),channel,destination,status,0,channel==NotificationChannel.IN_APP?null:Instant.now(),delivered,null));}@Transactional(readOnly=true)public NotificationSlice mine(String user,int page,int size){return notifications.findByRecipient(user,Math.max(0,page),Math.max(1,Math.min(50,size)));}@Transactional(readOnly=true)public NotificationSlice unread(String user,int page,int size){return notifications.findUnreadByRecipient(user,Math.max(0,page),Math.max(1,Math.min(50,size)));}@Transactional(readOnly=true)public long unreadCount(String user){return notifications.countUnread(user);}@Transactional public Notification read(String user,UUID id){Notification n=notifications.findById(id).orElseThrow(()->new NoSuchElementException("Notification not found"));if(!n.recipientId().equals(user))throw new NoSuchElementException("Notification not found");return notifications.save(n.read(Instant.now()));}@Transactional public int readAll(String user){return notifications.markAllRead(user);}@Transactional public void delete(String user,UUID id){Notification n=notifications.findById(id).orElseThrow(()->new NoSuchElementException("Notification not found"));if(!n.recipientId().equals(user))throw new NoSuchElementException("Notification not found");notifications.delete(id);}@Transactional(readOnly=true)public NotificationPreference preferences(String user){return preferences.find(user).orElse(NotificationPreference.defaults(user,null));}@Transactional public NotificationPreference updatePreferences(String user,boolean inApp,boolean email,boolean push,String address,String token,String locale){return preferences.save(new NotificationPreference(user,inApp,email,push,address,token,locale,Instant.now()));}}
